"wk_import_staging_records","policy":"Authenticated users can update wk_import_staging_records","cmd":"UPDATE","permissive":"PERMISSIVE","roles":"{public}","qual":"(auth.role() = 'authenticated'::text)","with_check":"(auth.role() = 'authenticated'::text)"},{"schema":"public","tablename":"wk_ingestion_runs","policy":"Authenticated users can insert wk_ingestion_runs","cmd":"INSERT","permissive":"PERMISSIVE","roles":"{public}","qual":null,"with_check":"(auth.role() = 'authenticated'::text)"},{"schema":"public","tablename":"wk_ingestion_runs","policy":"Authenticated users can read wk_ingestion_runs","cmd":"SELECT","permissive":"PERMISSIVE","roles":"{public}","qual":"(auth.role() = 'authenticated'::text)","with_check":null},{"schema":"public","tablename":"wk_ingestion_runs","policy":"Authenticated users can update wk_ingestion_runs","cmd":"UPDATE","permissive":"PERMISSIVE","roles":"{public}","qual":"(auth.role() = 'authenticated'::text)","with_check":null},{"schema":"public","tablename":"wk_magazine_featured_artists","policy":"Admin manage featured artists","cmd":"ALL","permissive":"PERMISSIVE","roles":"{public}","qual":"(auth.role() = 'authenticated'::text)","with_check":null},{"schema":"public","tablename":"wk_magazine_visual_assets","policy":"Authenticated users can insert wk_magazine_visual_assets","cmd":"INSERT","permissive":"PERMISSIVE","roles":"{public}","qual":null,"with_check":"(auth.role() = 'authenticated'::text)"},{"schema":"public","tablename":"wk_magazine_visual_assets","policy":"Authenticated users can read wk_magazine_visual_assets","cmd":"SELECT","permissive":"PERMISSIVE","roles":"{public}","qual":"(auth.role() = 'authenticated'::text)","with_check":null},{"schema":"public","tablename":"wk_magazine_visual_assets","policy":"Authenticated users can update wk_magazine_visual_assets","cmd":"UPDATE","permissive":"PERMISSIVE","roles":"{public}","qual":"(auth.role() = 'authenticated'::text)","with_check":"(auth.role() = 'authenticated'::text)"}]$wkrows$::jsonb;
  r record;
  current_row record;
  after_row record;
  new_qual text;
  new_check text;
  policy_sql text;
  applied integer := 0;
BEGIN
  IF jsonb_array_length(expected) <> 80 THEN
    RAISE EXCEPTION 'STOP: expected 80 policies';
  END IF;
  FOR r IN SELECT * FROM jsonb_to_recordset(expected)
    AS x(schema text, tablename text, policy text, cmd text, permissive text, roles text, qual text, with_check text)
    ORDER BY schema, tablename, policy
  LOOP
    SELECT p.cmd,p.permissive,p.roles::text AS roles,p.qual,p.with_check
    INTO current_row FROM pg_policies p
    WHERE p.schemaname=r.schema AND p.tablename=r.tablename AND p.policyname=r.policy;
    IF NOT FOUND
      OR current_row.cmd IS DISTINCT FROM r.cmd
      OR current_row.permissive IS DISTINCT FROM r.permissive
      OR current_row.roles IS DISTINCT FROM r.roles
      OR current_row.qual IS DISTINCT FROM r.qual
      OR current_row.with_check IS DISTINCT FROM r.with_check
    THEN
      RAISE EXCEPTION 'STOP: RLS authority drift at %.%.%',r.schema,r.tablename,r.policy;
    END IF;
    IF (coalesce(r.qual,'')||coalesce(r.with_check,'')) NOT LIKE '%auth.uid()%'
      AND (coalesce(r.qual,'')||coalesce(r.with_check,'')) NOT LIKE '%auth.role()%'
    THEN RAISE EXCEPTION 'STOP: no auth function in %.%.%',r.schema,r.tablename,r.policy;
    END IF;
    new_qual := replace(replace(r.qual,'auth.uid()','(select auth.uid())'),'auth.role()','(select auth.role())');
    new_check := replace(replace(r.with_check,'auth.uid()','(select auth.uid())'),'auth.role()','(select auth.role())');
    policy_sql := format('ALTER POLICY %I ON %I.%I',r.policy,r.schema,r.tablename);
    IF r.qual IS NOT NULL THEN policy_sql := policy_sql || format(' USING (%s)',new_qual); END IF;
    IF r.with_check IS NOT NULL THEN policy_sql := policy_sql || format(' WITH CHECK (%s)',new_check); END IF;
    EXECUTE policy_sql;
    SELECT p.cmd,p.permissive,p.roles::text AS roles,p.qual,p.with_check
    INTO after_row FROM pg_policies p
    WHERE p.schemaname=r.schema AND p.tablename=r.tablename AND p.policyname=r.policy;
    IF after_row.cmd IS DISTINCT FROM r.cmd
      OR after_row.permissive IS DISTINCT FROM r.permissive
      OR after_row.roles IS DISTINCT FROM r.roles
      OR (r.qual IS NULL AND after_row.qual IS NOT NULL)
      OR (r.with_check IS NULL AND after_row.with_check IS NOT NULL)
      OR (r.qual IS NOT NULL AND after_row.qual IS NULL)
      OR (r.with_check IS NOT NULL AND after_row.with_check IS NULL)
      OR ((coalesce(r.qual,'')||coalesce(r.with_check,'')) LIKE '%auth.uid()%'
          AND (coalesce(after_row.qual,'')||coalesce(after_row.with_check,'')) NOT LIKE '%SELECT auth.uid()%')
      OR ((coalesce(r.qual,'')||coalesce(r.with_check,'')) LIKE '%auth.role()%'
          AND (coalesce(after_row.qual,'')||coalesce(after_row.with_check,'')) NOT LIKE '%SELECT auth.role()%')
    THEN
      RAISE EXCEPTION 'STOP: postcondition failed for %.%.%',r.schema,r.tablename,r.policy;
    END IF;
    applied := applied+1;
  END LOOP;
  IF applied<>80 THEN RAISE EXCEPTION 'STOP: wrong applied count %',applied; END IF;
END
$wkbatch$;
